import { Pool, PoolClient } from 'pg';

interface TransferResult {
  fromAccountId: string;
  toAccountId: string;
  amount: number;
  newFromBalance: number;
  newToBalance: number;
}

export class WalletService {
  constructor(private readonly pool: Pool) {}

  /**
   * Transfers `amount` from `fromAccountId` to `toAccountId` atomically.
   * Locks both account rows with SELECT ... FOR UPDATE before mutating
   * balances, so concurrent transfers touching the same account serialize
   * instead of racing on a stale balance read.
   */
  async transfer(
    fromAccountId: string,
    toAccountId: string,
    amount: number,
  ): Promise<TransferResult> {
    const client: PoolClient = await this.pool.connect();

    try {
      await client.query('BEGIN');

      // Lock the source row first, in the order the ids were passed in.
      const sourceResult = await client.query(
        'SELECT id, balance FROM accounts WHERE id = $1 FOR UPDATE',
        [fromAccountId],
      );
      if (sourceResult.rowCount === 0) {
        throw new Error(`Account ${fromAccountId} not found`);
      }
      const sourceBalance = Number(sourceResult.rows[0].balance);

      // Then lock the destination row.
      const destResult = await client.query(
        'SELECT id, balance FROM accounts WHERE id = $1 FOR UPDATE',
        [toAccountId],
      );
      if (destResult.rowCount === 0) {
        throw new Error(`Account ${toAccountId} not found`);
      }
      const destBalance = Number(destResult.rows[0].balance);

      if (sourceBalance < amount) {
        throw new Error(
          `Insufficient balance on account ${fromAccountId}: has ${sourceBalance}, needs ${amount}`,
        );
      }

      await client.query(
        'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
        [amount, fromAccountId],
      );
      await client.query(
        'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
        [amount, toAccountId],
      );

      await client.query(
        `INSERT INTO ledger_entries (account_id, entry_type, amount, related_account_id)
         VALUES ($1, 'DEBIT', $2, $3)`,
        [fromAccountId, amount, toAccountId],
      );
      await client.query(
        `INSERT INTO ledger_entries (account_id, entry_type, amount, related_account_id)
         VALUES ($1, 'CREDIT', $2, $3)`,
        [toAccountId, amount, fromAccountId],
      );

      await client.query('COMMIT');

      return {
        fromAccountId,
        toAccountId,
        amount,
        newFromBalance: sourceBalance - amount,
        newToBalance: destBalance + amount,
      };
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    } finally {
      client.release();
    }
  }
}
